mod = 998244353

def power(a, b):
    if b == 0:
        return 1
    elif b % 2 == 0:
        return power(a * a % mod, b // 2) % mod
    else:
        return (power(a * a % mod, b // 2) * a) % mod

def count_strings(n, k, sa):
    dp = [1] * n
    prefix = [1] * n
    for i in range(1, n):
        if sa[i] < sa[i - 1]:
            dp[i] = (dp[i - 1] * power(k, n - sa[i - 1] - 1)) % mod
            prefix[i] = prefix[i - 1] * power(k - 1, n - sa[i] - 1) * power(k, sa[i - 1]) % mod
            prefix[i] += 1
        else:
            dp[i] = dp[i - 1]
            prefix[i] = prefix[i - 1]
    return sum(dp) % mod

