# Define the Doe graph generation function
def generate_doe_graph(order):
    if order == 0:
        return dict([(1, [1])])
    elif order == 1:
        return dict([(1, [1]), (2, [1])])
    else:
        # Generate D(2) from D(1)
        graph = generate_doe_graph(order - 1)
        order_1 = {1: graph[1]}
        order_2 = {2: graph[2]}

        # Update graph based on order_1 and order_2
        for v in order_1:
            graph[v+1] = (order + 1) + graph[v+1]
            for key in order_2:
                graph[key] = (order + 1) + graph[key]

        order_new = order + 1
        graph[order_new] = [order_new, order_new + 1]
        return graph

