from collections import deque

def deep(visited, queue):
    while queue:
        x, y = queue.popleft()
        for dx, dy in [[0, 1], [1, 0]]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

def solve(n):
    c = [int(input()) for _ in range(n)]
    r = [int(input()) for _ in range(n)]
    grid = [[0 for _ in range(n)] for _ in range(n)]
    q = deque()
    for i in range(n):
        for j in range(n):
            if i == 0:
                grid[0][j] = c[j]
                q.append([0, j])
            if j == 0:
                grid[i][0] = r[i]
                q.append([i, 0])
    while q:
        x, y = q.popleft()
        if grid[x][y]:
            continue
        grid[x][y] = 1
        if x + 1 < n:
            grid[x+1][y] = 1
        if y + 1 < n:
            grid[x][y+1] = 1
        q.extend([(x+1, y), (x, y+1)])
    for cell in grid:
        q = deque([cell.index(1)])
        visited = {(0, 0), (0, 0)}
        deep(visited, q)
        assert len(visited) == n * n // 2
