from typing import List

def is_permutation_possible(A: List[int]) -> bool:
    unique = set(A)
    return len(unique) == len(A)

def find_valid_X(A: List[int]) -> (bool, int):
    A.sort()
    n = len(A)
    max_val = max(A)
    min_val = min(A)

    # If range is too large, no permutation is possible
    if max_val - min_val >= 2 * 10**7:
        return (False, None)

    # Try different values for X
    for X in range(1, 2 * 10**7 + 1):
        counts = [0] * (max_val - min_val + 1)
        for val in A:
            counts[val - min_val] += 1
        if (all(count == 1 for count in counts) and len(set(A)) == (n - 1)):
            return (True, X)

    return (False, None)

def process_cases(T: int, cases: List[List[int]]) -> List[str]:
