# Function to calculate the minimum number of moves a knight can make
def min_knight_moves(moves):
    if moves < 2:
        return 2
    if moves == 2:
        return 4
    if moves == 3:
        return 6
    if moves == 4:
        return 9
    return moves + 1

# Function to return the board configuration for the knight
def knight_config(to_move, moves):
    steps = min_knight_moves(to_move)
    config = ''
    turns = deque()
    queue = deque([(0, 0, 0)])
    when_hit = set()
    current = 1
    while queue:
        row, col, turn = queue.popleft()
        if turn == turns and (row, col) in when_hit:
            if config[-2:] * 2 not in config:
                config += 'X'
        else:
            when_hit.add((row, col, turn))
            if turn == steps:
                turns.append(build(next_turn(moves)))
            else:
                if (row + steps, col) not in when_hit:
                    queue.append((row + steps, col, turn + 1))
                if (row, col + steps) not in when_hit:
                    queue.append((row, col + steps, turn + 1))
                break
    return config

# Function that updates the next turn
def next_turn(left):
    steps = min_knight_moves(left)
    while False not in [c in '.X' for c in build(steps + 1)]:
        steps += 1
    return build(steps + 1)

# Function that builds the new board configuration
def build(moves):
    row, col = 0, 0
    build_map = ['' for _ in range(moves + 1)]
    build_map[1] = ['X']
    while row < moves:
        col = 0
        while col < moves:
            if abs(row - 1) == abs(col - 0):
                build_map[1].append('.')
            elif abs(row - row / (1 + steps) + (col - 0) / steps) == 1:
                build_map[1].append('X')
            else:
                build_map[1].append('O')
            col += 1
        break
    for i in range(2, moves + 1):
        build_map[i] = []
        for j in range(len(build_map[i - 1])):
            if build_map[i - 1][j] == '.':
                if (j - 1) * (j - 1) + (i - 1) * (i - 1) == row * row + col * col:
                    build_map[i].append('X')
                    break
                else:
                    build_map[i].append('.')
    return ''.join(build_map[moves])

