from random import randint

def find_opportunities(e, v, c):
    if e < 2:
        raise Exception("e must be at least 2.")

    opportunities = set()
    for l in range(2, e + 1):
        for r in range(l, e + 1):
            opportunities.add(max(v[l-1:r], key=lambda x: (x * 100, c[r-1])))

    return opportunities

def sample_opportunities(e, t, n):
    if e < 2:
        raise Exception("e must be at least 2.")

    k = 2 * e * (e + 1) // 2
    if k > n:
        raise Exception(f"Too many candidates ({k}).")

    return list(combinations(range(e + 1), t))[randint(0, k - 1)]

def evaluate(opportunities, e):
    prob = 0
    max_val = min_val = 0

    for opportunity in opportunities:
        val, idx = max(opportunity, key=lambda x: (x * 100, x))
        prob += 1 / len(opportunities)
        if val > max_val:
            max_val = val
            max_op = opportunity.copy()
        if val < min_val:
            min_val = val
            min_op = opportunity.copy()

    return (prob * max_val, prob * min_val)

def expected_grade(n, k):
    e = n + 1

    opportunities = find_opportunities(e, v, c)
    start = randint(0, n - 1)

    sorted_opportunities = opportunities.select(start) + opportunities.select(n - start)

    sample_size = 2 * e * (e + 1) // 2
    sample_start = 2 * start + 1
    sample_end = 2 * (n - start) + 1
    sample_opportunities = sample_opportunities(e, sample_size)

    expected_val = sum(o / k for o in opportunities) * (k - 1) / k

    return (1 - (expected_val - expected_grade(sample_size, sample_start, sample_end)) / expected_val) * float('nan') or expected_grade(sample_size, sample_start, sample_end)

