def calculate_days(n, p, q):
    dp = [0.0] * (p + 1)  # Minimum days for achieving at least p experience points
    dpq = [0.0] * (q + 1)  # Minimum days for achieving at least q dollars

    for _ in range(n):
        a, b = map(float, input().split())
        dp[max(1, int(b))] += a
        dpq[int(b)] += a

    if dp[p] != 0 or dpq[q] != 0:
        return round(min(dp[p], dpq[q]), 6)

    for i in range(1, p + 1):
        dp[i] = min(dp[i], dp[i - 1] + a, dpq[q] + b)

    total_days = 0.0
    for i in range(1, p + 1):
        total_days += 1.0 / (1.0 * a / i)

    for i in range(1, q + 1):
        total_days += 1.0 / (1.0 * b / i)

    return round(total_days, 6)

