import sys

def find_min_days():
    n, p, q = map(int, input().split())
    projects = []
    for _ in range(n):
        a, b = map(int, input().split())
        projects.append((a, b))

    min_days = float('inf')
    dp = [sys.maxsize] * (p + 1)  # Dynamic Programming to keep track of experience level

    for day in range(1, 1000001):
        for a, _ in projects:
            if day * a <= p:
                dp[day * a] = min(dp[day * a], dp[day])
            if day * a + day < q:
                dp[day + day] = min(dp[day + day], dp[day // a] + day)
            if day >= p and day < q:
                dp[day + day] = min(dp[day + day], dp[day])

    for _ in range(p + 1, q + 1):
        min_days = min(min_days, dp[_])

    return min_days

