from collections import deque

def findPortalOffsets(i, r, c):
    n = len(r)
    if i == r[i-1] or i == c[n-i]:
        return [0, n+1]
    if i < r[i-1]:
        if c[i] <= r[i]:
            return [i+1, i+1]
        else:
            return [i+1, c[n-i+1]+1]
    else:
        for j in range(c[i], n + 1):
            if r[i] <= j <= r[i-1] + (j > r[i]) + (j < c[i]):
                return [(i-1)*n + j, (i-1)*n + j]
            if j > c[n-i-1]:
                return [(i+n-2)*n + j, (i+n-2)*n + j]

def solve(n):
    portals = []
    r = [0] + *map(int, input().split())
    c = [0] + *map(int, input().split())
    for i in range(1, n):
        x, y = findPortalOffsets(i, r, c)
        if x == 0 or y == n+1:
            return -1
        if r[i-1] == c[i]:
            for j in range(x, y+1):
                portals.append((i-1, j))
        else:
            for j in range(x, n + 1):
                portals.append((i-1, j))
            for j in range(1, y+1):
                portals.append((i, n + j))
                for k in range(1, j):
                    portals.append((i - 1, n - k))
                    portals.append((i - 1, n + k))
    return str(len(portals) // 2)
