def parse_input():
    n, b = map(int, input().split())
    arrows = []
    for _ in range(n):
        x0, y0, x1, y1 = map(int, input().split())
        arrows.append((x0, y0, x1, y1))
    q = int(input())
    plans = []
    for _ in range(q):
        xi, yi, wi, ti = input().split()
        plans.append((xi, yi, wi, int(ti)))

    return n, b, arrows, plans

def simulate(t, xi, yi, arrow):
    x, y = arrow
    dx, dy = 1 if wi == 'R' or wi == 'D' else -1, 
    timer = ti
    while True:
        ani = min(1, min(timer, t))
        x += dx * ani
        y += dy * ani
        timer -= ani
        if x < 0 or x > b or y < 0 or y > b:
            return x, y
        elif x == b and y == b:
            return b-1, b-1

def process_input(n, b, arrows, plan):
    last = None
    for i, (x0, y0, x1, y1) in enumerate(arrows):
        lo, hi = x0, x1
        if y0 > y1:
            lo, hi = y0, y1
        for x in range(lo, hi+1):
            area = (x0 == x) or (y0 == y and x0 != lo)
            if area and x == xi and y == yi:
                last = i
                break
        if last:
            if not area and ti <= t:
                return ti - ti % (b-1)

    while last is None:
        ti = max(ti-1, 1)
        for i, (x0, y0, x1, y1) in enumerate(arrows):
            lo, hi = x0, x1
            if y0 > y1:
                lo, hi = y0, y1
            for x in range(lo, hi):
                area = (x0 == x or x1 == x) or (y0 == y and x0 != lo)
                if area and x == xi and y == yi:
                    last = i
                    break
        if last:
            if not area and ti <= t:
                return ti - ti % (b-1)

    if plan[2] == 'L':
        return b, b
    elif plan[2] == 'U':
        return b-1, b-1
    elif plan[2] == 'R':
        return b, 0
    else:
        return 0, 0

def main():
