import math

def find_next(x, y, dir):
    if dir == 'U':
        return x, y+1
    elif dir == 'D':
        return x, y-1
    elif dir == 'L':
        return x-1, y
    elif dir == 'R':
        return x+1, y

def find_first(x, y, bs):
    bx, by, ewx, ewy = bs
    if x <= bx or x >= ewx:
        return 'L' if x < bx else 'R'
    elif y < by or y >= ewy:
        return 'U' if y < by else 'D'
    else:
        return find_first(3, 3, bs)

def solve_next(x, y, dir, bs, time):
    bx, by, ewx, ewy = bs
    x, y = x-ewx, y-ewy
    d = math.gcd(x, y)
    x, y = x//d, y//d
    dst = -x + y * (time + 1)
    ut = 1 if x > 0 else -1
    id = 1 if d > 0 else -1
    xu = b if dir == 'L' else 'R'
    yu = b if dir == 'U' else 'D'

    x += id
    y += ut
    if (x, y) == (0, 0) or (x, y) == (time, time+1):
        return
    elif (x, y) in (bs, find_first(x, y, bs)):
        return
    elif not (x <= by or x >= ewx):
        solve_next(x, y, xu, bs, time+1)
    elif not (y <= by or y >= ewy):
        solve_next(x, y, yu, bs, time+1)

