    if sorted(r) != list(range(1, n + 1)) or sorted(c) != list(range(1, n + 1)):
        return -1

    portals = []
    queue = deque([(1, 1)])
    visited = [[False] * n for _ in range(n)]
    visited[1][1] = True

    while queue:
        x, y = queue.popleft()

        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + direction[0], y + direction[1]

            if 1 <= nx <= n and 1 <= ny <= n and not visited[nx][ny]:
                queue.append((nx, ny))
                visited[nx][ny] = True

    for i in range(n):
        for j in range(n):
            if visited[i + 1][j + 1]:
                portals.append((i + 1, j + 1, n + 1 - i, j + 1))
                portals.append((i + 1, j + 1, j + 1, n + 1 - j))

    return len(portals)

