import sys
from collections import defaultdict

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if xroot == yroot:
        return
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def findpathcompliance(n, parents, d):
    rank = [0] * n
    parent = list(range(n))
    for i in range(n):
        p = parents[i]
        if p == -1:
            continue
        union(parent, rank, i, p)
    comp = {}
    comp[find(parent, i)] = i for i in range(n)
    for i in range(n):
        p = parents[i]
        if p != -1 and p in comp and i in comp:
            comp[find(parent, i)] = [j for j in comp if j in comp and j != i and p == parent[j]]
    return [[comp[j]] for j in range(n)]

