def escape_smart_beaver(n, b, arrows, q, plans):
    grid = [[(1e18, None) for _ in range(b+1)] for _ in range(b+1)]
    grid[b][b] = (0, None)

    for d in range(4):
        y0, x0, y1, x1 = arrows[d]
        if y0 == y1 or x0 == x1:
            for ii in range(min(y0, y1) + 1, max(y0, y1)):
                grid[ii][x0] = (ii, 'L' if d == 0 else 'R')
                grid[y0][x0] = (ii - y0 + 1, 'U' if d == 0 else 'D')
            for ii in range(max(y0, y1) + 1, min(y0, y1)):
                grid[ii][x0] = (ii, 'R' if d == 0 else 'L')
                grid[y1][x0] = (ii - y1 + 1, 'D' if d == 0 else 'U')
        else:
            for ii in range(min(x0, x1) + 1, max(x0, x1)):
                grid[y0][ii] = (ii, 'U' if d == 0 else 'D')
                grid[y0][x0] = (ii - x0 + 1, 'L' if d == 0 else 'R')
            for ii in range(max(x0, x1) + 1, min(x0, x1)):
                grid[y0][ii] = (ii, 'R' if d == 0 else 'L')
                grid[y0][x1] = (ii - x1 + 1, 'D' if d == 0 else 'U')

