        if dir not in ['U', 'D', 'L', 'R']:
            raise ValueError("Invalid direction: " + dir)
        if not can_move_to(x, y, r, c) or not can_move_to(x + t, y, r, c):
            raise ValueError("Beaveractor leaves the campus")
        if can_move_to(x + t // 2, y + t // 2, r, c):
            x1, y1 = move_in_direction(x + t // 2, y + t // 2, dir, r, c)
        else:
