from collections import Counter

def eat_orphans(arr):
    heads, reversed, pairs = [], [], Counter()
    for s in arr:
        n = len(s)
        for i, j in zip(s[:n//2], s[-(n//2-n%2):][::-1]):
            if i == j:
                continue
            if s[0] != s[-1]:
                heads.append(i != j)
                pairs[j] += (i != j)
                pairs[i] -= (i != j)
                reversed.append(i)
                break
        else:
            reversed.append(s)
    min_needed = max(0, sum(values for values in reversed.values()) // 2)
    pairs[''] -= sum(values for values in reversed.values())
    return all(c == balances for c, balances in pairs.items()), heads, pairs

def cover_heads(arr, heads):
    ans = heads[0]
    for a, h in zip(arr, heads):
        change = min(1, (h - ans) % 2)
        ans = change + h
        for a, h in zip(arr, heads):
            a, h = a[:len(arr) // 2] + a[-(len(arr) // 2) + (len(arr) % 2):][::-1], h[-(-len(arr) // 2):(len(arr) // 2) + 1][::-1][0]
            continue
    return ans + heads[1:]

def get_mins(tests):
    heads = []
    for T in range(int(input())):
        N, M = map(int, input().split())
        A = [input() for _ in range(N)]
        all_palindromes, heads, prefixes = eat_orphans(A)
        changers = morsers = s = 0
        for a, _, k, v in prefixes:
            found_all = all_palindromes[k]
            if not all_palindromes[k] and found_all:
                changers += len(v)
            elif found_all:
                prefixes.pop(k)
        heads = cover_heads(A, heads)
        if not all_palindromes:
            return -1
        s += changers + heads[0]
        for a, h in zip(A, heads):
            change = min(1, (h - s) % 2)
            s = change + h
        yield s

T = int(input())
for T in range(int(input())):
