# Function to perform Bellman-Ford to find the shortest path in D(n)
def bellman_ford(d, s, t, n):
    if d[t] != math.inf:
        return 0
    for i in range(n + 1):
        d[t] = min([d[x] + d[x][d[x][-1]] for x in range(s, n + 1) if x != d[x][0]], default=math.inf)
    return d[t]

# Function to find the length of the shortest path in D(n)
def find_path_length(d, s, t, n):
    dist = bellman_ford(dst, s, t, n)
    return 1 + dist[-1]

